// Priority 1 runs before redirect_canonical(), which would turn ?author=1 into /author/username/.
add_action( 'template_redirect', 'perfectpixel_disable_author_archives', 1 );
add_filter( 'author_link', 'perfectpixel_disable_author_archives_link', 20 );
add_filter( 'wp_sitemaps_add_provider', 'perfectpixel_disable_author_archives_sitemap', 20, 2 );

function perfectpixel_disable_author_archives() {
	if ( ! is_author() && ! isset( $_GET['author'] ) ) {
		return;
	}
	global $wp_query;
	$wp_query->set_404();
	status_header( 404 );
	nocache_headers();
}

function perfectpixel_disable_author_archives_link( $link ) {
	return is_admin() ? $link : home_url( '/' );
}

function perfectpixel_disable_author_archives_sitemap( $provider, $name ) {
	return 'users' === $name ? false : $provider;
}
